"""Compile separate frontend files into read-only payload resources."""
from pathlib import Path
import sys


def generate(output: Path) -> None:
    root = Path(__file__).resolve().parents[1]
    resources = (('ui.html', 'ui.html'), ('styles.css', 'styles.css'), ('app.js', 'app.js'), ('i18n.js', 'i18n.js'), ('logo.png', 'assets/logo.png'))
    lines = [
        '/* Generated by tools/embed_assets.py. Edit the original frontend files. */',
        '#include "assets.h"',
        '#include <string.h>',
        '',
    ]
    for index, (name, path) in enumerate(resources):
        data = (root / path).read_bytes()
        if not data:
            raise SystemExit(f'Frontend file is empty: {name}')
        lines.append(f'static const unsigned char resource_{index}[] = {{')
        for offset in range(0, len(data), 16):
            lines.append('  ' + ', '.join(f'0x{byte:02x}' for byte in data[offset:offset + 16]) + ',')
        lines.extend(['};', ''])
    lines.append('static const XaAsset resources[] = {')
    for index, (name, path) in enumerate(resources):
        lines.append(f'  {{"{name}", resource_{index}, sizeof(resource_{index})}},')
    lines.extend([
        '};',
        '',
        'const XaAsset *xa_asset_get(const char *name) {',
        '  for (size_t i = 0; i < sizeof(resources) / sizeof(resources[0]); i++)',
        '    if (!strcmp(resources[i].name, name)) return &resources[i];',
        '  return NULL;',
        '}',
        '',
    ])
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text('\n'.join(lines), encoding='ascii', newline='\n')


if __name__ == '__main__':
    generate(Path(sys.argv[1]) if len(sys.argv) > 1 else Path('build/assets.c'))
